import java.util.ArrayList;
import java.util.List;

public class RabinKarp {
    private static final long BASE = 256;
    private static final long MOD = 1_000_000_007L;

    public List<Integer> search(String t, String p) {
        List<Integer> result = new ArrayList<>();
        int n = t.length(), m = p.length();
        if (m > n) return result;

        long highOrder = 1; // BASE^(m-1) mod MOD
        for (int k = 0; k < m - 1; k++) highOrder = (highOrder * BASE) % MOD;

        long pHash = 0, wHash = 0;
        for (int k = 0; k < m; k++) {
            pHash = (pHash * BASE + p.charAt(k)) % MOD;
            wHash = (wHash * BASE + t.charAt(k)) % MOD;
        }

        for (int i = 0; i + m <= n; i++) {
            if (wHash == pHash && matches(t, i, p)) {
                result.add(i);
            }
            if (i + m < n) {
                wHash = (wHash - t.charAt(i) * highOrder % MOD + MOD) % MOD;
                wHash = (wHash * BASE + t.charAt(i + m)) % MOD;
            }
        }
        return result;
    }

    private boolean matches(String t, int start, String p) {
        for (int k = 0; k < p.length(); k++) {
            if (t.charAt(start + k) != p.charAt(k)) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println(new RabinKarp().search("abedabcabc", "abc"));
    }
}

