def search(t: str, p: str) -> list[int]:
    BASE, MOD = 256, 1_000_000_007
    n, m = len(t), len(p)
    if m > n:
        return []

    high_order = pow(BASE, m - 1, MOD)  # BASE^(m-1) mod MOD
    p_hash = w_hash = 0
    for k in range(m):
        p_hash = (p_hash * BASE + ord(p[k])) % MOD
        w_hash = (w_hash * BASE + ord(t[k])) % MOD

    result: list[int] = []
    for i in range(n - m + 1):
        if w_hash == p_hash and t[i:i + m] == p:  # verify on hash match
            result.append(i)
        if i + m < n:
            w_hash = (w_hash - ord(t[i]) * high_order) % MOD
            w_hash = (w_hash * BASE + ord(t[i + m])) % MOD
    return result


if __name__ == "__main__":
    print(search("abedabcabc", "abc"))
